      dueDate: '2026-10-10',
      lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    },
    {
      number: 'INV-002',
      customerId: 'CUST-B',
      status: 'issued',
      dueDate: '2026-10-01',
